js='''document.addEventListener('DOMContentLoaded',()=>{const prog=document.querySelector('.reading-progress');if(prog){window.addEventListener('scroll',()=>{const d=document.documentElement;prog.style.width=(100*window.scrollY/Math.max(1,d.scrollHeight-innerHeight))+'%'},{passive:true})}document.querySelectorAll('[data-insight]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();const panel=document.querySelector('.detail-overlay'),t=el.getAttribute('data-insight');if(panel){panel.querySelector('[data-detail-title]').textContent=t;panel.querySelector('[data-detail-copy]').textContent=({'SEC':'미국 증권거래위원회. 규칙의 제안·확정·시행 상태를 구별해 확인해야 합니다.','DART':'대한민국 전자공시시스템. 기업 재무와 공시의 원문 출처를 우선 확인합니다.','판례':'법원 판단에는 사실관계, 적용법령, 선고일과 법원별 차이가 있습니다. 원문 확인 후 해석해야 합니다.','연준':'미 연방준비제도. 기준금리 발표와 실제 규제·법률 변화는 구별해서 해석합니다.'}[t]||'관련 경제·법률 자료를 검증 후 정리합니다.');panel.classList.add('open');panel.querySelector('.close').focus()}}));document.querySelectorAll('.detail-overlay .close').forEach(x=>x.addEventListener('click',()=>x.closest('.detail-overlay').classList.remove('open')));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.detail-overlay')?.classList.remove('open')});document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);b.textContent='링크 복사됨'}catch{b.textContent='주소창 링크를 복사하세요'}}));document.querySelectorAll('[data-demo-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('[role=status]').textContent='시안입니다. 실제 뉴스레터 발송은 운영 구독 API 연결 후 제공됩니다.'}))});'''
